"use client"

import { RSCPathnameNormalizer } from "next/dist/server/normalizers/request/rsc";
import { use, useEffect, useState } from "react"
import { toast } from "sonner";

export default function Dashboard() {
    const [name, setName] = useState<string>('');
    const [email, setEmail] = useState<string>('');
    const [roomId, setRoomId] = useState<string>('');
    const [customerId, setCustomerId] = useState<string>('');
    const [loading, setLoading] = useState<boolean>(false);


    useEffect(() => {
        async function booking() {
            try {
                setLoading(true);
                const res = await fetch('http://localhost:3001/booking', {
                    method: 'GET',
                    headers: { 'Content-type': 'application/json' },
                })

                const data = await res.json();
                if (!res.ok) return toast.error(data.error);

                setRoomId(data.result.rows.room_id);
                setCustomerId(data.result.rows.customer_id);

                toast.success('Booking details fetched!')

            } catch (error: any) {
                console.error(error);
                toast.error(error.message);
                return;

            } finally {
                setLoading(false);
            }
        }
        booking();
    }, [])

    return (
        <div>

        </div>
    )
}
